<?php
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/teacher_evaluation.php';
require_login();
register_shutdown_function(function(){ require __DIR__.'/includes/module_switcher.php'; });

$user=current_user()??[];
$isAdmin=($user['role']??'')==='admin';
$isLeader=($user['role']??'')==='totruong'||in_array('totruong',(array)($user['groups']??[]),true);
$canAll=$isAdmin||($user['role']??'')==='bgh'||can_perm_level('td.all_data','view');
$canOpen=$isAdmin||can_perm_level('td.teacher_rating','view')||can_perm_level('td.stats','view')||can_perm_level('cm.baocao.dugio','view');
if(!$canOpen){http_response_code(403);exit('Tài khoản chưa được cấp quyền xem hồ sơ đánh giá giáo viên.');}

$teachers=te_teachers();$linkedName=trim((string)($user['teacher_name']??$user['name']??''));$linkedTeacher=null;
foreach($teachers as $teacher)if(te_norm($teacher['name']??'')===te_norm($linkedName)){$linkedTeacher=$teacher;break;}
$linkedTeam=$linkedTeacher?te_teacher_team($linkedTeacher):'';
$scopeTeachers=array_values(array_filter($teachers,function($teacher)use($canAll,$isLeader,$linkedTeacher,$linkedTeam){
    if($canAll)return true;
    if($isLeader&&$linkedTeam!=='')return te_norm(te_teacher_team($teacher))===te_norm($linkedTeam);
    return $linkedTeacher&&(string)($teacher['id']??'')===(string)($linkedTeacher['id']??'');
}));

$year=csdl_year_current()??['id'=>'','label'=>SCHOOL_YEAR,'start'=>date('Y').'-09-01','end'=>(date('Y')+1).'-05-31'];
$period=te_period($year,(string)($_GET['period_type']??'month'),(string)($_GET['anchor']??date('Y-m-d')),(string)($_GET['from']??''),(string)($_GET['to']??''));
$config=te_config();$observations=te_observations();$fileChecks=te_file_checks();$td=load_json(DATA_PATH.'/thidua.json',['records'=>[]]);$tdRecords=$td['records']??[];
$results=[];foreach($scopeTeachers as $teacher)$results[(string)($teacher['id']??'')]=te_calculate($teacher,$period,$config,$observations,$fileChecks,$tdRecords);
$reviews=te_reviews();
foreach($results as $teacherId=>&$result){$saved=$reviews[te_review_key($period,$teacherId)]??[];if(($saved['status']??'')==='locked'&&is_array($saved['snapshot']??null))$result=$saved['snapshot'];}unset($result);
if(empty($_SESSION['te_csrf']))$_SESSION['te_csrf']=bin2hex(random_bytes(20));$csrf=$_SESSION['te_csrf'];

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
    $action=(string)($_POST['action']??'');
    if($action==='save_config'){
        if(!$isAdmin){http_response_code(403);exit('Chỉ quản trị được sửa công thức đánh giá.');}
        $new=$config;
        $new['version']=2;$new['groups']=[];$groupIds=[];
        foreach((array)($_POST['group_id']??[]) as $i=>$rawId){$id=preg_replace('/[^a-zA-Z0-9_-]/','',(string)$rawId);$name=trim((string)($_POST['group_name'][$i]??''));if($id===''||$name===''||isset($groupIds[$id]))continue;$groupIds[$id]=true;$new['groups'][]=['id'=>$id,'name'=>$name,'max'=>max(0,(float)($_POST['group_max'][$i]??0))];}
        if(!$new['groups']){flash('Cần giữ lại ít nhất một nhóm/cột đánh giá.','danger');header('Location: '.BASE_URL.'danhgia.php?view=settings');exit;}
        $catalog=te_source_catalog();$new['criteria']=[];
        foreach((array)($_POST['criterion_id']??[]) as $i=>$rawId){$id=preg_replace('/[^a-zA-Z0-9_-]/','',(string)$rawId);$name=trim((string)($_POST['criterion_name'][$i]??''));$groupId=(string)($_POST['criterion_group'][$i]??'');$source=(string)($_POST['criterion_source'][$i]??'');$operation=(string)($_POST['criterion_operation'][$i]??'add');if($id===''||$name===''||!isset($groupIds[$groupId])||!isset($catalog[$source]))continue;$new['criteria'][]=['id'=>$id,'name'=>$name,'group_id'=>$groupId,'source'=>$source,'operation'=>$operation==='subtract'?'subtract':'add','points'=>max(0,(float)($_POST['criterion_points'][$i]??0))];}
        $labels=['Hoàn thành xuất sắc','Hoàn thành tốt','Hoàn thành','Không hoàn thành'];$new['ratings']=[];
        foreach($labels as $i=>$label)$new['ratings'][]=['min'=>max(0,(float)($_POST['rating_min'][$i]??0)),'label'=>$label];
        $new['updated_by']=$user['name']??'';$new['updated_at']=date('c');save_json(DATA_PATH.'/teacher_evaluation_config.json',$new);if(function_exists('cds_audit_log'))cds_audit_log('evaluation_config_updated','teacher_evaluation',['version'=>$new['version']??1]);
        flash('Đã lưu công thức đánh giá. Các kỳ đã khóa vẫn giữ nguyên ảnh chụp kết quả.');header('Location: '.BASE_URL.'danhgia.php?view=settings');exit;
    }
    if($action==='review'){
        $teacherId=(string)($_POST['teacher_id']??'');$result=$results[$teacherId]??null;
        if(!$result){http_response_code(403);exit('Giáo viên nằm ngoài phạm vi quản lý.');}
        $status=(string)($_POST['status']??'');$allowed=false;
        if($status==='teacher_checked'&&$linkedTeacher&&(string)($linkedTeacher['id']??'')===$teacherId)$allowed=true;
        if($status==='leader_confirmed'&&$isLeader&&te_norm($result['team'])===te_norm($linkedTeam))$allowed=true;
        if(in_array($status,['approved','locked'],true)&&$canAll)$allowed=true;
        if(!$allowed){http_response_code(403);exit('Bạn không có quyền xác nhận trạng thái này.');}
        $key=te_review_key($period,$teacherId);$old=$reviews[$key]??[];
        if(($old['status']??'')==='locked'&&!$isAdmin){http_response_code(403);exit('Kỳ đánh giá đã khóa.');}
        $reviews[$key]=array_merge($old,['id'=>$key,'period'=>$period,'teacher_id'=>$teacherId,'teacher_name'=>$result['teacher_name'],'team'=>$result['team'],'status'=>$status,'note'=>trim((string)($_POST['note']??'')),'snapshot'=>$result,'updated_by'=>$user['name']??'','updated_at'=>date('c')]);
        save_json(DATA_PATH.'/teacher_evaluation_reviews.json',$reviews);if(function_exists('cds_audit_log'))cds_audit_log('evaluation_status_updated','teacher_evaluation',['teacher_id'=>$teacherId,'period'=>$period['key'],'status'=>$status]);flash('Đã cập nhật trạng thái hồ sơ đánh giá.');header('Location: '.$_SERVER['REQUEST_URI']);exit;
    }
}

$teamFilter=trim((string)($_GET['team']??''));$teacherFilter=trim((string)($_GET['teacher_id']??''));
$filtered=array_values(array_filter($results,fn($row)=>($teamFilter===''||$row['team']===$teamFilter)&&($teacherFilter===''||$row['teacher_id']===$teacherFilter)));
usort($filtered,fn($a,$b)=>$b['total']<=>$a['total']?:strnatcasecmp($a['teacher_name'],$b['teacher_name']));
$teams=array_values(array_unique(array_column($results,'team')));sort($teams,SORT_NATURAL|SORT_FLAG_CASE);
$view=in_array($_GET['view']??'overview',['overview','profile','settings'],true)?($_GET['view']??'overview'):'overview';if($view==='settings'&&!$isAdmin)$view='overview';
$profileId=(string)($_GET['id']??($linkedTeacher['id']??''));$profile=$results[$profileId]??null;
$statusLabels=[''=>'Đang tổng hợp','teacher_checked'=>'Giáo viên đã kiểm tra','leader_confirmed'=>'Tổ trưởng đã xác nhận','approved'=>'BGH đã duyệt','locked'=>'Đã khóa'];
function te_query(array $extra=[]): string {return http_build_query(array_merge($_GET,$extra));}
function te_group_score(array $result,string $id): float {if(isset($result['group_scores'][$id]))return (float)$result['group_scores'][$id];return (float)($result[$id]??0);}
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hồ sơ đánh giá giáo viên – CDS</title>
